'use client';

/**
 * Grid Audio Visualizer
 * A clean, retro lo-fi dot-matrix visualizer inspired by LiveKit Agents UI.
 * Pure floating dots on transparent background (zero dark container / zero black circle).
 */

import React, { useEffect, useRef } from 'react';

export type GridState = 'idle' | 'listening' | 'thinking' | 'speaking';

export interface GridVisualizerProps {
  state?: GridState;
  color?: string; // Hex color e.g. '#0284c7'
  volume?: number; // 0.0 ~ 1.0 (大声变大)
  size?: number; // px width & height
  className?: string;
}

const DEFAULT_COLOR = '#0284c7';

function hexToRgb(hexColor: string): [number, number, number] {
  const match = hexColor.match(/^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$/);
  if (match) {
    return [
      parseInt(match[1], 16),
      parseInt(match[2], 16),
      parseInt(match[3], 16),
    ];
  }
  return [2, 132, 199]; // #0284c7
}

export function GridVisualizer({
  state = 'idle',
  color = DEFAULT_COLOR,
  volume = 0,
  size = 260,
  className = '',
}: GridVisualizerProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const stateRef = useRef(state);
  stateRef.current = state;
  const volumeRef = useRef(volume);
  volumeRef.current = volume;
  const colorRef = useRef(color);
  colorRef.current = color;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let startTime = performance.now();
    let smoothedVol = 0;

    // Grid configuration: 9x9 matrix
    const COLS = 9;
    const ROWS = 9;
    const CENTER_C = 4;
    const CENTER_R = 4;

    function render(now: number) {
      if (!ctx || !canvas) return;
      const t = (now - startTime) / 1000;
      const targetVol = volumeRef.current;
      smoothedVol += (targetVol - smoothedVol) * 0.15; // Smooth audio volume response

      const currentState = stateRef.current;
      const [r, g, b] = hexToRgb(colorRef.current);

      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, width, height);

      // Grid dimensions and spacing
      const pad = 24;
      const availableSize = Math.min(width, height) - pad * 2;
      const spacing = availableSize / (COLS - 1);
      const startX = (width - (COLS - 1) * spacing) / 2;
      const startY = (height - (ROWS - 1) * spacing) / 2;

      for (let row = 0; row < ROWS; row++) {
        for (let col = 0; col < COLS; col++) {
          const x = startX + col * spacing;
          const y = startY + row * spacing;
          const distFromCenter = Math.hypot(col - CENTER_C, row - CENTER_R);

          let intensity = 0.22; // Base dot opacity on light canvas
          let dotRadius = 3.6;

          switch (currentState) {
            case 'idle': {
              // Gentle radial breathing ripple
              const wave = Math.sin(t * 2.8 - distFromCenter * 0.75);
              const crest = Math.max(0, wave);
              intensity = 0.2 + crest * 0.55;
              dotRadius = 3.5 + crest * 2.0;
              break;
            }

            case 'listening': {
              // Expansive radar rings
              const wave = Math.sin(t * 4.8 - distFromCenter * 0.95);
              const isPeak = Math.max(0, wave);
              intensity = 0.22 + isPeak * 0.78;
              dotRadius = 3.5 + isPeak * 2.8;
              break;
            }

            case 'thinking': {
              // Rotating orbital chase
              const angle = Math.atan2(row - CENTER_R, col - CENTER_C);
              const spin = Math.sin(angle * 2.0 - t * 4.5 + distFromCenter * 0.65);
              const isOrbit = Math.max(0, spin);
              intensity = 0.2 + isOrbit * 0.75;
              dotRadius = 3.5 + isOrbit * 2.6;
              break;
            }

            case 'speaking': {
              // 大声变大: audio amplitude equalizer & concentric energetic surge
              const volEnergy = Math.max(0.18, smoothedVol);
              const radiusThreshold = 0.6 + volEnergy * 4.6;
              const inRadius = distFromCenter <= radiusThreshold;

              // Sound band modulation per column
              const colWave = Math.sin(t * 14.0 + col * 1.1) * 0.5 + 0.5;
              const rowDist = Math.abs(row - CENTER_R);
              const eqHighlight = (volEnergy * 4.5 * colWave) >= rowDist;

              if (inRadius || eqHighlight) {
                const centerProximity = 1.0 - (distFromCenter / 5.7);
                intensity = Math.min(1.0, 0.45 + volEnergy * 0.55 + centerProximity * 0.2);
                dotRadius = 3.8 + volEnergy * 4.0 * (0.65 + centerProximity * 0.35);
              } else {
                intensity = 0.2;
                dotRadius = 3.4;
              }
              break;
            }
          }

          // Draw the matrix dot with smooth anti-aliasing
          ctx.beginPath();
          ctx.arc(x, y, dotRadius, 0, Math.PI * 2);

          if (intensity > 0.42) {
            // Glowing illuminated state
            ctx.shadowColor = `rgba(${r}, ${g}, ${b}, ${Math.min(0.9, intensity * 0.85)})`;
            ctx.shadowBlur = 10;
            ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${intensity})`;
          } else {
            // Subtle baseline dot
            ctx.shadowColor = 'transparent';
            ctx.shadowBlur = 0;
            ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${intensity})`;
          }

          ctx.fill();
        }
      }

      ctx.restore();
      animId = requestAnimationFrame(render);
    }

    // Set pixel ratio resolution
    const dpr = window.devicePixelRatio || 1;
    canvas.width = size * dpr;
    canvas.height = size * dpr;

    animId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animId);
    };
  }, [size]);

  return (
    <div
      className={`grid-visualizer-container relative flex items-center justify-center select-none ${className}`}
      style={{ width: size, height: size }}
    >
      <canvas
        ref={canvasRef}
        style={{ width: size, height: size }}
        className="block pointer-events-none"
      />
    </div>
  );
}
'use client';

import { useEffect, useRef, useState } from 'react';
import {
  ArrowRight,
  Bot,
  Check,
  ChevronRight,
  Maximize2,
  MessageCircle,
  Mic,
  Minimize2,
  RotateCcw,
  Send,
  SlidersHorizontal,
  Sparkles,
  Square,
  Volume2
} from 'lucide-react';
import { createStreamingPlayer } from '@/lib/streaming-audio';
import { VOICES, type VoiceId } from '@/lib/voices';
import { SCENARIOS } from '@/lib/scenarios';
import type { ConversationMessage, FeedbackReport } from '@/lib/contracts';
import { useVoiceSession } from '@/hooks/use-voice-session';
import { Avatar, type AvatarState } from './avatar';

type Difficulty = 'friendly' | 'neutral' | 'challenging';
type Setup = { gemini: boolean; gradium: boolean };

async function responseError(response: Response) {
  const body = await response.json().catch(() => null);
  return typeof body?.error === 'string' ? body.error : 'Something went wrong. Please try again.';
}

function SoundWave({ active = false, color = 'blue' }: { active?: boolean; color?: 'blue' | 'slate' }) {
  return (
    <div className={`sound-wave ${active ? 'active' : ''} sound-wave-${color}`} aria-hidden="true">
      <span /><span /><span /><span /><span /><span /><span />
    </div>
  );
}

export function Coach() {
  const [scenarioId, setScenarioId] = useState('interview');
  const [voiceId, setVoiceId] = useState<VoiceId>('marshall');
  const [preparingVoice, setPreparingVoice] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>('neutral');
  const [customScenario, setCustomScenario] = useState('');
  const [started, setStarted] = useState(false);
  const [messages, setMessages] = useState<ConversationMessage[]>([]);
  const [draft, setDraft] = useState('');
  const [state, setState] = useState<AvatarState>('idle');
  const [busy, setBusy] = useState(false);
  const [micStarting, setMicStarting] = useState(false);
  const [recordingSeconds, setRecordingSeconds] = useState(0);
  const [stageMaximized, setStageMaximized] = useState(false);
  const [error, setError] = useState('');
  const [report, setReport] = useState<FeedbackReport | null>(null);
  const [setup, setSetup] = useState<Setup | null>(null);
  const [setupFailed, setSetupFailed] = useState(false);

  const recorder = useVoiceSession();
  const lock = useRef(false);
  const generation = useRef(0);
  const controller = useRef<AbortController | null>(null);
  const player = useRef<ReturnType<typeof createStreamingPlayer> | null>(null);
  const transcriptEnd = useRef<HTMLDivElement | null>(null);

  const scenario = SCENARIOS.find(item => item.id === scenarioId) ?? SCENARIOS[0];
  const voice = VOICES.find(item => item.id === voiceId) ?? VOICES[0];
  const counterpartRole = ({
    interview: 'Interviewer',
    raise: 'Your manager',
    relationship: 'Your partner',
    feedback: 'Your colleague',
    custom: 'Your counterpart'
  } as Record<string, string>)[scenarioId];
  const counterpart = `${voice.name} · ${counterpartRole}`;
  const hasUserTurn = messages.some(message => message.role === 'user');

  function stopAudio() {
    player.current?.stop();
  }

  function getPlayer() {
    player.current ??= createStreamingPlayer();
    return player.current;
  }

  useEffect(() => {
    const abort = new AbortController();
    fetch('/api/status', { signal: abort.signal }).then(async response => {
      if (!response.ok) throw new Error();
      setSetup(await response.json());
    }).catch(() => { if (!abort.signal.aborted) setSetupFailed(true); });
    return () => { abort.abort(); controller.current?.abort(); stopAudio(); };
  }, []);

  useEffect(() => {
    transcriptEnd.current?.scrollIntoView({ block: 'nearest', behavior: 'instant' });
  }, [messages, busy]);

  // Recording duration timer
  useEffect(() => {
    let timer: NodeJS.Timeout | null = null;
    if (recorder.isRecording) {
      setRecordingSeconds(0);
      timer = setInterval(() => {
        setRecordingSeconds(s => Math.min(60, s + 1));
      }, 1000);
    } else {
      setRecordingSeconds(0);
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [recorder.isRecording]);

  function reset() {
    generation.current += 1;
    controller.current?.abort();
    recorder.cancelRecording();
    stopAudio();
    lock.current = false;
    setStarted(false); setMessages([]); setDraft(''); setReport(null);
    setError(''); setState('idle'); setBusy(false); setMicStarting(false); setPreparingVoice(false);
  }

  async function speak(text: string, token: number, signal: AbortSignal) {
    if (!setup?.gradium) return;
    setPreparingVoice(true);
    try {
      const response = await fetch('/api/speak', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text, voiceId, format: 'pcm' }),
        signal
      });
      if (!response.ok) throw new Error(await responseError(response));
      if (token !== generation.current) return;
      await getPlayer().play(response, signal, () => {
        if (token === generation.current) {
          setPreparingVoice(false);
          setState('speaking');
        }
      });
    } catch (cause) {
      if (token === generation.current && !signal.aborted) {
        setError(cause instanceof Error ? `${cause.message} You can continue by typing.` : 'Speech unavailable. You can continue by typing.');
      }
    } finally {
      if (token === generation.current) {
        setPreparingVoice(false);
        stopAudio();
      }
    }
  }

  function begin() {
    if (!setup?.gemini || (scenarioId === 'custom' && !customScenario.trim())) return;
    setMessages([{ role: 'assistant', content: scenario.openingLine }]);
    setStarted(true); setError('');
  }

  async function sendTurn(text: string, token: number, signal: AbortSignal, speechReady = true) {
    const next: ConversationMessage[] = [...messages, { role: 'user', content: text }];
    setMessages(next); setDraft(''); setState('thinking');
    const response = await fetch('/api/converse', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scenarioId, difficulty, customScenario, messages: next }),
      signal
    });
    if (!response.ok) throw new Error(await responseError(response));
    const { reply } = await response.json();
    if (token !== generation.current) return;
    setMessages([...next, { role: 'assistant', content: reply }]);
    if (speechReady) await speak(reply, token, signal);
  }

  async function runTurn(source: 'text' | 'voice') {
    if (lock.current || !setup?.gemini || (source === 'text' && !draft.trim())) return;
    lock.current = true; setBusy(true); setError(''); stopAudio();
    const token = generation.current;
    const abort = new AbortController(); controller.current = abort;
    try {
      let speechReady = !!setup?.gradium;
      if (speechReady) {
        try { await getPlayer().prepare(); }
        catch {
          speechReady = false;
          if (token === generation.current) {
            stopAudio();
            setError('Audio could not start. Your reply will appear in the transcript.');
          }
        }
      }
      if (token !== generation.current || abort.signal.aborted) return;
      let text = draft.trim();
      if (source === 'voice') {
        setState('thinking');
        const blob = await recorder.stopRecording();
        const response = await fetch('/api/transcribe', {
          method: 'POST',
          headers: { 'Content-Type': 'audio/wav' },
          body: blob,
          signal: abort.signal
        });
        if (!response.ok) throw new Error(await responseError(response));
        text = (await response.json()).text;
      }
      if (token === generation.current && text.trim()) await sendTurn(text, token, abort.signal, speechReady);
    } catch (cause) {
      if (token === generation.current && !abort.signal.aborted) {
        setError(cause instanceof Error ? cause.message : 'Could not send your answer. Please try again.');
      }
    } finally {
      if (token === generation.current) {
        lock.current = false; setBusy(false); setState('idle'); setPreparingVoice(false);
      }
    }
  }

  async function toggleRecording() {
    if (recorder.isRecording) { await runTurn('voice'); return; }
    if (lock.current || busy) return;
    const token = generation.current;
    lock.current = true; setBusy(true); setMicStarting(true);
    setError(''); stopAudio();
    try { await recorder.startRecording(); }
    catch { /* Recorder displays its actionable error. */ }
    finally {
      if (token === generation.current) {
        lock.current = false; setBusy(false); setMicStarting(false); setPreparingVoice(false);
      }
    }
  }

  async function finish() {
    if (lock.current || !hasUserTurn || recorder.isRecording) return;
    lock.current = true; setBusy(true); setState('thinking'); setError(''); stopAudio();
    const token = generation.current;
    const abort = new AbortController(); controller.current = abort;
    try {
      const response = await fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scenarioId, difficulty, customScenario, messages }),
        signal: abort.signal
      });
      if (!response.ok) throw new Error(await responseError(response));
      const feedback = await response.json();
      if (token === generation.current) setReport(feedback);
    } catch (cause) {
      if (token === generation.current && !abort.signal.aborted) {
        setError(cause instanceof Error ? cause.message : 'Could not create feedback. Try again.');
      }
    } finally {
      if (token === generation.current) {
        lock.current = false; setBusy(false); setState('idle'); setPreparingVoice(false);
      }
    }
  }

  const avatarState = recorder.isRecording ? 'listening' : state;
  const statusText = micStarting
    ? 'Connecting your microphone'
    : recorder.isRecording
    ? 'Listening to you'
    : preparingVoice
    ? 'Preparing voice'
    : state === 'thinking'
    ? 'Thinking it through'
    : state === 'speaking'
    ? `${counterpart.split(' · ')[0]} is speaking`
    : '';

  const gridClass = [
    'studio-grid',
    stageMaximized && 'stage-maximized'
  ].filter(Boolean).join(' ');

  return (
    <main className="app-shell">
      {/* TOPBAR */}
      <header className="topbar">
        <a href="/" className="brand" aria-label="Rehearsal home">
          <span className="brand-mark"><MessageCircle size={18} /></span>
          rehearsal<span className="brand-dot">.</span>
        </a>

        {/* TOP-RIGHT HORIZONTAL CAPSULE FOR SCENARIO SWITCHING */}
        <div className="topbar-right">
          <nav className="scenario-capsule" aria-label="Scenarios">
            {SCENARIOS.map((item, index) => (
              <button
                key={item.id}
                className={`scenario-pill ${scenarioId === item.id ? 'active' : ''}`}
                disabled={started}
                onClick={() => setScenarioId(item.id)}
              >
                <span className="pill-symbol">{['↗', '€', '♡', '↔', '+'][index]}</span>
                <span className="pill-title">{item.title}</span>
              </button>
            ))}
          </nav>

          <div className="session-chip">
            <span />
            {report ? 'Session complete' : started ? 'In progress' : 'Ready'}
          </div>
        </div>
      </header>

      {/* PAGE HEADING */}
      <section className="page-heading">
        <div>
          <div className="eyebrow">{scenario.title.toUpperCase()}</div>
          <h1>
            {report
              ? 'Take the practice with you.'
              : started
              ? 'You’ve got the floor.'
              : 'Big conversation? Start here.'}
          </h1>
        </div>
      </section>

      {/* CUSTOM SCENARIO EDIT BANNER */}
      {scenarioId === 'custom' && (
        <div className="custom-scenario-banner">
          <div className="custom-scenario-card">
            <div className="custom-header">
              <span className="eyebrow">CUSTOM SCENARIO CONFIGURATION</span>
              <button
                type="button"
                className="custom-close-btn"
                onClick={() => setScenarioId('interview')}
                title="Switch to default scenario"
              >
                ×
              </button>
            </div>
            <label htmlFor="custom-prompt">
              Who are you speaking to, and what do you want to say?
            </label>
            <textarea
              id="custom-prompt"
              maxLength={2000}
              disabled={started}
              value={customScenario}
              onChange={event => setCustomScenario(event.target.value)}
              placeholder="e.g. Speaking with senior partner who is reluctant to approve a budget increase..."
            />
          </div>
        </div>
      )}

      {/* SETUP ALERTS */}
      {(setupFailed || (setup && !setup.gemini)) && (
        <div className="setup-notice" role="status">
          <strong>{setupFailed ? 'Could not check service availability.' : 'Connect Gemini to start practising.'}</strong>{' '}
          {setupFailed ? 'Refresh the page to try again.' : 'Add GEMINI_API_KEY to the server environment, then restart the app.'}
        </div>
      )}
      {setup?.gemini && !setup.gradium && (
        <div className="setup-notice" role="status">
          Voice is unavailable until GRADIUM_API_KEY is configured. You can practise by typing.
        </div>
      )}

      {/* REPORT VIEW OR ACTIVE STUDIO */}
      {report ? (
        <section className="report-layout">
          <div className="report-card">
            <div className="eyebrow">SESSION NOTES</div>
            <h2>A stronger next conversation.</h2>
            <p className="report-summary">{report.summary}</p>
            <div className="feedback-grid">
              <div>
                <h3><Check size={17} /> What worked</h3>
                {report.strengths.map((item, index) => <p key={index}>{item}</p>)}
              </div>
              <div>
                <h3><Sparkles size={17} /> Try next time</h3>
                {report.improvements.map((item, index) => <p key={index}>{item}</p>)}
              </div>
            </div>
            <div className="suggested">
              <span className="eyebrow">WORDS TO MAKE YOUR OWN</span>
              <blockquote>“{report.suggestedResponse}”</blockquote>
            </div>
            <button className="primary" onClick={reset}>
              <RotateCcw size={16} /> Practise another conversation
            </button>
          </div>
          <aside className="report-side">
            <Avatar state="idle" gender={voice.gender} scenario={scenarioId} difficulty={difficulty} />
            <h3>Practice counts.</h3>
            <span>Session held in this browser only.</span>
          </aside>
        </section>
      ) : (
        <div className={gridClass}>
          {/* CENTER: REHEARSAL STAGE */}
          <section className="stage-panel">
            <div className="stage-top">
              <span className={`difficulty-badge mood-${difficulty}`}>{difficulty}</span>

              <button
                className="stage-tool-btn stage-tool-icon"
                onClick={() => setStageMaximized(!stageMaximized)}
                aria-label={stageMaximized ? "Restore view" : "Maximize stage"}
                title={stageMaximized ? "Exit full view" : "Full stage"}
              >
                {stageMaximized ? <Minimize2 size={15} /> : <Maximize2 size={15} />}
              </button>
            </div>

            <div className="avatar-stage">
              <div className="stage-orbit" />
              <Avatar state={avatarState} gender={voice.gender} scenario={scenarioId} difficulty={difficulty} />

              <div className="stage-persona">
                <span className="counterpart-name">{counterpart}</span>
                {avatarState === 'speaking' && (
                  <SoundWave active={true} color="blue" />
                )}
              </div>

              {statusText && (
                <div className={`state-indicator state-${avatarState}`}>
                  <span />
                  {statusText}
                </div>
              )}
            </div>

            <div className="stage-bottom">
              {!started ? (
                <div className="stage-action-center">
                  <button
                    className="primary start-button"
                    disabled={!setup?.gemini || (scenarioId === 'custom' && !customScenario.trim())}
                    onClick={begin}
                  >
                    Start practising <ArrowRight size={17} />
                  </button>
                </div>
              ) : (
                <div className="stage-controls-area">
                  {/* Clean Horizontal Status Row in Whitespace (No Overlap, No Red Numbers) */}
                  {recorder.isRecording && (
                    <div className="recording-status-row" aria-live="polite">
                      <span className="rec-pulse-dot" />
                      <span className="rec-time-text">
                        {String(Math.floor(recordingSeconds / 60)).padStart(2, '0')}:
                        {String(recordingSeconds % 60).padStart(2, '0')} / 01:00
                      </span>
                      <SoundWave active={true} color="slate" />
                    </div>
                  )}

                  <div className="record-container">
                    <button
                      className={`record-button ${recorder.isRecording ? 'recording' : ''}`}
                      disabled={busy || !setup?.gradium}
                      onClick={toggleRecording}
                    >
                      {recorder.isRecording ? <Square size={18} fill="currentColor" /> : <Mic size={20} />}
                      <span>{recorder.isRecording ? 'Finish & send' : 'Record your answer'}</span>
                    </button>
                  </div>

                  <div className="session-actions">
                    <button
                      disabled={busy || !hasUserTurn || recorder.isRecording}
                      onClick={finish}
                    >
                      End session & get feedback <ChevronRight size={14} />
                    </button>
                    <button className="reset-button" onClick={reset} aria-label="Reset session">
                      <RotateCcw size={15} />
                    </button>
                  </div>
                </div>
              )}
            </div>
          </section>

          {/* RIGHT: TRANSCRIPT PANEL */}
          <section className="transcript-panel">
            {/* Top Compact Settings Strip (Model, Voice, Approach) */}
            <div className="persona-settings-strip">
              <div className="setting-chip" title="Voice">
                <Mic size={13} className="chip-icon" />
                <label htmlFor="voice" className="chip-label">Their voice</label>
                <select
                  id="voice"
                  value={voiceId}
                  disabled={started}
                  onChange={event => setVoiceId(event.target.value as VoiceId)}
                  className="chip-select"
                >
                  {VOICES.map(item => (
                    <option key={item.id} value={item.id}>{item.label}</option>
                  ))}
                </select>
              </div>

              <div className="setting-chip" title="Approach">
                <SlidersHorizontal size={13} className="chip-icon" />
                <label htmlFor="difficulty" className="chip-label">Their approach</label>
                <select
                  id="difficulty"
                  value={difficulty}
                  disabled={started}
                  onChange={event => setDifficulty(event.target.value as Difficulty)}
                  className="chip-select"
                >
                  <option value="friendly">Friendly</option>
                  <option value="neutral">Neutral</option>
                  <option value="challenging">Challenging</option>
                </select>
              </div>

              <div className="setting-chip model-chip" title="Active Model">
                <Bot size={13} className="chip-icon" />
                <span className="chip-text">Gemini 2.5</span>
              </div>
            </div>

            <div className="panel-heading">
              <div className="transcript-title">
                <Volume2 size={15} />
                <span>Conversation</span>
              </div>
              <span className="turn-count-badge">
                {messages.length > 0 ? `${messages.filter(m => m.role === 'user').length} turns` : 'Ready'}
              </span>
            </div>

            <div className="transcript" aria-live="polite" aria-relevant="additions">
              {messages.length === 0 ? (
                <div className="empty-transcript">
                  <span><MessageCircle size={24} /></span>
                  <h3>The first words are yours.</h3>
                </div>
              ) : (
                messages.map((message, index) => {
                  const isUser = message.role === 'user';
                  const userTurnNumber = messages.slice(0, index + 1).filter(m => m.role === 'user').length;

                  return (
                    <div key={index} className="message-wrapper">
                      {isUser && (
                        <div className="turn-divider">
                          <span className="turn-divider-label">Round {userTurnNumber}</span>
                        </div>
                      )}
                      <div className={`message message-${message.role}`}>
                        <div className="message-header">
                          <span className="message-author">
                            {isUser ? 'You' : counterpart.split(' · ')[0]}
                          </span>
                        </div>
                        <p>{message.content}</p>
                      </div>
                    </div>
                  );
                })
              )}

              {busy && state !== 'speaking' && (
                <div className="thinking-message">
                  <span /><span /><span />
                  <small>{preparingVoice ? 'Preparing voice' : hasUserTurn ? 'Preparing a response' : 'Working on it'}</small>
                </div>
              )}
              <div ref={transcriptEnd} />
            </div>

            {(error || recorder.error) && (
              <p className="error-message" role="alert">{error || recorder.error}</p>
            )}

            <form className="composer" onSubmit={event => { event.preventDefault(); void runTurn('text'); }}>
              <label className="sr-only" htmlFor="answer">Your answer</label>
              <textarea
                id="answer"
                placeholder={started ? 'Or type your answer…' : 'Start a session to join'}
                value={draft}
                onChange={event => setDraft(event.target.value)}
                disabled={!started || busy || recorder.isRecording}
                maxLength={4000}
                rows={2}
              />
              <button aria-label="Send answer" disabled={!started || busy || recorder.isRecording || !draft.trim()}>
                <Send size={16} />
              </button>
            </form>
          </section>
        </div>
      )}

      {/* FOOTER */}
      <footer className="footer">
        <span>Conversation Coach</span>
        <span>Voice by Gradium <span className="footer-divider">/</span> Gemini</span>
      </footer>
    </main>
  );
}
@import 'tailwindcss';

:root {
  /* BORDERLESS CLEAN CANVAS PALETTE (SESAME / LINEAR INSPIRED) */
  --bg-core: #f8fafc;
  --bg-surface: #ffffff;
  --border-hairline: rgba(15, 23, 42, 0.07);
  --border-subtle: rgba(15, 23, 42, 0.12);
  --border-focus: #2563eb;

  --ink: #0f172a;
  --ink-secondary: #334155;
  --muted: #64748b;
  --subtle: #94a3b8;

  --blue: #2563eb;
  --blue-soft: #eff6ff;
  --blue-glow: rgba(37, 99, 235, 0.18);
  --emerald: #059669;
  --crimson: #e11d48;

  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Plus Jakarta Sans', Inter, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background-color: var(--bg-core);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 15px; /* 字体基准适度展开 */
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button, input, textarea, select { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.45; }
button, a, input, textarea, select { -webkit-tap-highlight-color: transparent; }

button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 2px;
}

button { transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1); }
button:not(:disabled):active { transform: translateY(1px); }
button svg { flex-shrink: 0; }
a { color: inherit; text-decoration: none; }

.app-shell {
  max-width: 1560px;
  padding: 0 48px;
  margin: auto;
}

/* TOPBAR */
.topbar {
  height: 82px; /* 适当展开高度 */
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-hairline);
}

.brand {
  display: flex;
  align-items: center;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.6px;
  gap: 10px;
  color: var(--ink);
}

.brand-mark {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  background: var(--blue);
  border-radius: 9px;
  color: white;
}

.brand-dot {
  color: var(--blue);
  margin-left: -7px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 68px;
  border-bottom: 1px solid var(--border-hairline);
  gap: 16px;
}

.topbar-left {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

/* HORIZONTAL CAPSULE FOR SCENARIOS */
.scenario-capsule {
  display: inline-flex;
  align-items: center;
  background: rgba(15, 23, 42, 0.04);
  padding: 3px 4px;
  border-radius: 9999px;
  border: 1px solid var(--border-hairline);
  gap: 2px;
  max-width: 100%;
}

.scenario-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 13px;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  white-space: nowrap;
}

.scenario-pill:hover:not(:disabled) {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.6);
}

.scenario-pill.active {
  color: var(--ink);
  background: #ffffff;
  font-weight: 600;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.08);
}

.pill-symbol {
  font-size: 13px;
  opacity: 0.75;
}

.pill-title {
  letter-spacing: -0.1px;
}

/* CUSTOM SCENARIO BANNER */
.custom-scenario-banner {
  padding: 4px 0 16px;
}

.custom-scenario-card {
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 16px;
  padding: 16px 20px;
  box-shadow: 0 4px 16px -2px rgba(15, 23, 42, 0.04);
}

.custom-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.custom-close-btn {
  background: transparent;
  border: none;
  font-size: 18px;
  line-height: 1;
  color: var(--muted);
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 6px;
}

.custom-scenario-card label {
  display: block;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  margin-bottom: 8px;
}

.custom-scenario-card textarea {
  width: 100%;
  min-height: 64px;
  padding: 10px 14px;
  font-size: 13.5px;
  line-height: 1.5;
  border: 1px solid var(--border-hairline);
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.015);
  color: var(--ink);
  font-family: inherit;
  resize: vertical;
}

.custom-scenario-card textarea:focus {
  outline: none;
  border-color: var(--blue);
  background: #ffffff;
}

/* PAGE HEADING */
.page-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 34px 0 24px; /* 间距展开 */
}

.eyebrow {
  font-size: 11px;
  letter-spacing: 1.8px;
  font-weight: 700;
  color: var(--muted);
  font-family: var(--font-mono);
  text-transform: uppercase;
}

h1 {
  font-size: 34px; /* 标题字号展开 */
  letter-spacing: -0.8px;
  line-height: 1.25;
  margin: 6px 0 0;
  font-weight: 750;
  color: var(--ink);
}

.session-chip {
  font-size: 12px;
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--muted);
  background: var(--bg-surface);
  border: 1px solid var(--border-hairline);
  padding: 8px 16px;
  border-radius: 24px;
  font-family: var(--font-mono);
}

.session-chip > span {
  height: 7px;
  width: 7px;
  background: var(--blue);
  border-radius: 50%;
}

/* STUDIO GRID */
.studio-grid {
  display: grid;
  grid-template-columns: minmax(420px, 1fr) 390px;
  gap: 36px;
  align-items: stretch;
  min-height: 640px;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Stage Maximized Variation */
.studio-grid.stage-maximized {
  grid-template-columns: 1fr;
}

.studio-grid.stage-maximized .transcript-panel {
  display: none;
}

/* BORDERLESS SECTIONS */
.stage-panel, .transcript-panel {
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
  position: relative;
}

.transcript-panel {
  display: flex;
  flex-direction: column;
  padding-left: 36px;
  border-left: 1px solid var(--border-hairline);
  min-height: 640px;
  max-height: 760px;
}

/* PERSONA & MODEL SETTINGS STRIP (RIGHT PANEL) */
.persona-settings-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.setting-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ffffff;
  padding: 5px 11px;
  border-radius: 20px;
  border: 1px solid var(--border-hairline);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
  font-size: 12px;
  color: var(--muted);
}

.chip-icon {
  color: var(--muted);
  flex-shrink: 0;
}

.chip-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--subtle);
  margin-right: 2px;
}

.chip-select {
  border: none;
  background: transparent;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink);
  cursor: pointer;
  outline: none;
  padding: 1px 2px;
  font-family: inherit;
}

.chip-select:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.model-chip {
  background: rgba(37, 99, 235, 0.04);
  border-color: rgba(37, 99, 235, 0.14);
}

.model-chip .chip-icon,
.model-chip .chip-text {
  color: var(--blue);
  font-weight: 600;
  font-size: 11.5px;
}

/* SCENARIO PANEL */
.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  font-family: var(--font-mono);
  padding-bottom: 14px;
}

.scenario-list {
  display: flex;
  flex-direction: column;
  gap: 8px; /* 间距展开 */
  margin-top: 8px;
}

.scenario-card {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 13px;
  background: transparent;
  border: 1px solid transparent;
  text-align: left;
  border-radius: 14px;
  padding: 12px 14px; /* padding 展开 */
  color: var(--ink);
  transition: all 0.15s ease;
}

.scenario-card:hover:not(:disabled) {
  background: rgba(15, 23, 42, 0.035);
}

.scenario-card.selected {
  background: #ffffff;
  border-color: var(--border-hairline);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
}

.scenario-card:disabled {
  opacity: 1;
  cursor: default;
}

.scenario-symbol {
  display: grid;
  place-items: center;
  background: #f1f5f9;
  color: var(--muted);
  border-radius: 10px;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  font-size: 17px;
}

.selected .scenario-symbol {
  background: var(--blue-soft);
  color: var(--blue);
}

.scenario-info {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

.scenario-card strong {
  display: block;
  font-size: 13.5px; /* 标题展开 */
  font-weight: 650;
  color: var(--ink);
}

.scenario-card small {
  display: block;
  font-size: 12px; /* 描述展开 */
  color: var(--muted);
  line-height: 1.4;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scenario-check {
  color: var(--blue);
  margin-left: auto;
  flex-shrink: 0;
}

.difficulty {
  border-top: 1px solid var(--border-hairline);
  padding-top: 20px;
  margin-top: 22px;
}

.difficulty label, .custom-label {
  font-weight: 650;
  font-size: 12px;
  color: var(--muted);
  display: block;
  margin-bottom: 7px;
}

.difficulty select {
  display: block;
  width: 100%;
  padding: 10px 12px; /* 展开尺寸 */
  margin-bottom: 16px;
  border: 1px solid var(--border-hairline);
  background: #ffffff;
  border-radius: 10px;
  font-size: 13.5px;
  color: var(--ink);
  transition: border-color 0.15s;
}

.difficulty select:focus {
  border-color: var(--blue);
  outline: none;
}

.custom-label {
  display: block;
  margin-top: 14px;
}

.custom-label textarea {
  width: 100%;
  border: 1px solid var(--border-hairline);
  background: #ffffff;
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 13px;
  color: var(--ink);
  min-height: 90px;
  resize: vertical;
}

.custom-label textarea:focus {
  border-color: var(--blue);
  outline: none;
}

/* STAGE PANEL (CENTER CANVAS) */
.stage-panel {
  display: flex;
  flex-direction: column;
}

.stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 18px;
}

.stage-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--muted);
  padding: 6px 10px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
}

.stage-tool-btn:hover {
  background: rgba(15, 23, 42, 0.045);
  color: var(--ink);
}

.stage-tool-icon {
  padding: 6px 8px;
}

.difficulty-badge {
  text-transform: capitalize;
  font-size: 11px;
  font-weight: 600;
  background: #f1f5f9;
  padding: 4px 12px;
  border-radius: 20px;
  color: var(--muted);
  font-family: var(--font-mono);
}

/* NEXT-GEN IMMERSIVE AVATAR (PORTRAIT + MICRO-INTERACTION) */
.avatar-stage {
  position: relative;
  display: flex;
  align-items: center;
  flex-direction: column;
  padding-top: 12px;
}

.stage-orbit {
  display: none;
}

/* RETRO LO-FI DOT-MATRIX GRID VISUALIZER (PURE FLOATING DOTS - NO DARK BACKGROUND) */
.avatar {
  width: 260px;
  height: 260px;
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.grid-avatar-stage {
  position: relative;
  width: 250px;
  height: 250px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.avatar-speaking .grid-avatar-stage {
  transform: scale(1.06);
}

.avatar-listening .grid-avatar-stage {
  transform: scale(1.03);
}

.avatar-thinking .grid-avatar-stage {
  transform: scale(0.97);
}

.stage-persona {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
  z-index: 1;
}

.counterpart-name {
  font-size: 18px; /* 名字字号展开 */
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.2px;
}

.state-indicator {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
  margin-top: 8px;
  z-index: 1;
  background: #ffffff;
  padding: 5px 14px;
  border-radius: 20px;
  border: 1px solid var(--border-hairline);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}

.state-indicator > span {
  height: 6px;
  width: 6px;
  background: #94a3b8;
  border-radius: 50%;
}

.state-listening > span {
  background: var(--emerald);
  box-shadow: 0 0 6px var(--emerald);
  animation: pulse 1s infinite;
}

.state-speaking > span {
  background: var(--blue);
  box-shadow: 0 0 6px var(--blue);
  animation: pulse 0.8s infinite;
}

/* SOUNDWAVE COMPONENT */
.sound-wave {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  height: 18px;
}

.sound-wave span {
  width: 3px;
  height: 4px;
  border-radius: 99px;
  background: currentColor;
  transition: height 0.2s ease;
}

.sound-wave-blue { color: var(--blue); }
.sound-wave-slate { color: var(--muted); }

.sound-wave.active span {
  animation: wave 1.1s ease-in-out infinite;
}

.sound-wave.active span:nth-child(1) { animation-delay: 0.1s; }
.sound-wave.active span:nth-child(2) { animation-delay: 0.3s; }
.sound-wave.active span:nth-child(3) { animation-delay: 0.5s; }
.sound-wave.active span:nth-child(4) { animation-delay: 0.15s; }
.sound-wave.active span:nth-child(5) { animation-delay: 0.4s; }
.sound-wave.active span:nth-child(6) { animation-delay: 0.25s; }
.sound-wave.active span:nth-child(7) { animation-delay: 0.45s; }

@keyframes wave {
  0%, 100% { height: 4px; }
  50% { height: 16px; }
}

.stage-bottom {
  text-align: center;
  margin-top: auto;
  padding: 20px 0;
  z-index: 2;
}

.stage-action-center {
  display: flex;
  justify-content: center;
  padding: 16px 0;
}

.stage-controls-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

/* HORIZONTAL STATUS ROW IN WHITESPACE */
.recording-status-row {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 7px 18px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 24px;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.04);
}

.rec-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--crimson);
  animation: pulse 1s infinite;
}

.rec-time-text {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.5px;
}

.primary {
  background: var(--blue);
  color: white;
  border: none;
  padding: 13px 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 30px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.primary:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.start-button {
  min-width: 220px;
}

.record-container {
  display: flex;
  justify-content: center;
}

.record-button {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  justify-content: center;
  min-width: 230px;
  background: var(--blue);
  color: white;
  border: none;
  border-radius: 30px;
  padding: 14px 28px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.record-button:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.record-button.recording {
  background: #0f172a;
  color: white;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.2);
}

.session-actions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  margin-top: 6px;
}

.session-actions button {
  border: 0;
  background: transparent;
  font-size: 12px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
}

.session-actions button:hover:not(:disabled) {
  background: rgba(15, 23, 42, 0.045);
  color: var(--ink);
}

.session-actions .reset-button {
  border-left: 1px solid var(--border-hairline);
  padding-left: 12px;
}

/* TRANSCRIPT PANEL */
.transcript-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  font-family: var(--font-mono);
}

.turn-count-badge {
  font-size: 11px;
  font-family: var(--font-mono);
  background: rgba(15, 23, 42, 0.04);
  padding: 3px 8px;
  border-radius: 12px;
  color: var(--muted);
}

.transcript {
  flex: 1;
