  border-color: rgba(37, 99, 235, 0.16);
  border-radius: 16px 16px 4px 16px;
  color: #1e3a8a;
}

.composer {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 20px;
  padding: 8px 10px;
  transition: all 0.2s;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.03);
}

.composer:focus-within {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.composer textarea {
  background: transparent;
  border: 0;
  resize: vertical;
  min-height: 42px;
  max-height: 150px;
  width: 100%;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--ink);
  padding: 6px 8px;
  outline: none;
}

.composer textarea::placeholder {
  color: var(--subtle);
}

.composer button {
  display: grid;
  place-items: center;
  background: var(--blue);
  color: white;
  border: 0;
  border-radius: 50%;
  height: 36px;
  width: 36px;
  flex-shrink: 0;
}

.composer button:hover:not(:disabled) {
  background: #1d4ed8;
}

.error-message {
  color: #b91c1c;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 10px;
  margin: 0 0 10px;
  padding: 9px 13px;
  font-size: 12px;
  line-height: 1.5;
}

.thinking-message {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 3px;
}

.thinking-message > span {
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: var(--blue);
  animation: pulse 1s infinite;
}

.thinking-message small {
  font-size: 12px;
  color: var(--muted);
  margin-left: 6px;
}

.footer {
  display: flex;
  justify-content: space-between;
  padding: 26px 0;
  font-size: 12px;
  color: var(--subtle);
  border-top: 1px solid var(--border-hairline);
  margin-top: 44px;
}

.footer-divider {
  margin: 0 7px;
}

.setup-notice {
  margin-bottom: 18px;
  border: 1px solid #fde68a;
  border-radius: 12px;
  background: #fffbeb;
  padding: 12px 16px;
  font-size: 13px;
  line-height: 1.5;
  color: #92400e;
}

.setup-notice strong {
  color: #b45309;
}

/* REPORT LAYOUT */
.report-layout {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 36px;
}

.report-card {
  padding: 36px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 18px;
}

.report-card h2 {
  font-size: 28px;
  letter-spacing: -0.6px;
  margin: 8px 0;
  color: var(--ink);
}

.report-summary {
  color: var(--ink-secondary);
  max-width: 700px;
  font-size: 14px;
  line-height: 1.6;
}

.feedback-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin: 26px 0;
}

.feedback-grid h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 11px;
  color: var(--ink);
}

.feedback-grid div:first-child h3 svg { color: var(--emerald); }
.feedback-grid div:last-child h3 svg { color: #d97706; }

.feedback-grid p {
  font-size: 13px;
  padding: 11px 14px;
  background: #f8fafc;
  border-radius: 10px;
  margin: 0 0 7px;
  line-height: 1.5;
  color: var(--ink-secondary);
}

.suggested {
  background: #fffbeb;
  border: 1px solid #fde68a;
  padding: 22px;
  border-radius: 14px;
  margin-bottom: 26px;
}

.suggested .eyebrow {
  color: #b45309;
}

.suggested blockquote {
  font-size: 16px;
  line-height: 1.55;
  margin: 9px 0 0;
  color: #78350f;
  font-style: italic;
}

.report-side {
  align-self: center;
  text-align: center;
  padding: 24px;
}

.report-side .avatar {
  width: 220px;
  margin: auto;
}

.report-side h3 {
  font-size: 19px;
  margin: 14px 0 5px;
  color: var(--ink);
}

.report-side > span {
  font-size: 11px;
  color: var(--subtle);
  display: block;
  margin-top: 9px;
  font-family: var(--font-mono);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

/* RESPONSIVE DESIGN */
@media (max-width: 1150px) {
  .app-shell { padding: 0 24px; }
  .studio-grid {
    grid-template-columns: minmax(360px, 1fr) 350px;
    gap: 24px;
  }
  .transcript-panel { padding-left: 20px; }
  .avatar { width: 240px; height: 240px; }
  .stage-orbit { width: 260px; height: 260px; }
  h1 { font-size: 28px; }
}

@media (max-width: 930px) {
  .topbar {
    height: auto;
    padding: 12px 0;
    flex-wrap: wrap;
    gap: 12px;
  }
  .topbar-right {
    width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }
  .studio-grid {
    grid-template-columns: 1fr;
  }
  .transcript-panel {
    border-left: none;
    border-top: 1px solid var(--border-hairline);
    padding-left: 0;
    padding-top: 24px;
    min-height: 380px;
  }
  .report-layout { grid-template-columns: 1fr; }
  .report-side { display: none; }
}

@media (max-width: 600px) {
  .app-shell { padding: 0 16px; }
  .topbar {
    height: auto;
    padding: 10px 0;
    flex-wrap: wrap;
    gap: 10px;
  }
  .topbar-right {
    width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .scenario-capsule {
    overflow-x: auto;
    scrollbar-width: none;
    white-space: nowrap;
    max-width: 100%;
  }
  .brand { font-size: 19px; }
  .page-heading { padding: 18px 0 14px; }
  h1 { font-size: 24px; }
  .session-chip { display: none; }
  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }
  .transcript-panel {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--border-hairline);
    padding-top: 18px;
  }
  .avatar { width: 220px; height: 220px; }
  .stage-orbit { width: 240px; height: 240px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *:before, *:after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

